One global, many small files
Every file under src/js is an IIFE that adds one member (occasionally two or three that belong together) to window.VM:
(function attachVM(globalThis) {
  /** JSDoc … */
  const simpsonEstimate = (f, lo, hi, n) =&gt; { … }

  globalThis.VM = {...globalThis.VM, numerical: {...globalThis.VM?.numerical, simpsonEstimate}}
})(window)
The spread-merge means files can load in any order as far as attaching goes; the manifest exists for the few real load-time dependencies (every *Pmf/*Pdf reads logGamma; the discreteMath color helpers read VM.plotting; the SVG fullscreen button reuses the Plotly button’s icon). mustPrecede in src/manifest.mjs records them and src/manifest.test.js enforces them, along with “every file on disk is listed exactly once”.

Three causal filters for a noisy scalar signal. All take a plain array and return one of the same length; none looks ahead, so each output matches what the filter would have produced running online, one sample at a time.
VM = window.VM
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)
noisy = {
  const rng = VM.sampling.seededRandom(7)
  const gaussian = VM.sampling.gaussianRandom(rng)
  const zs = []
  for (let i = 0; i &lt; 60; i++) zs.push(Math.sin(i / 8) + 0.3 * gaussian())
  return zs
}

The three side by side

viewof filterK = Inputs.range([1, 15], {label: "moving-average window k", step: 1, value: 5})
viewof filterAlpha = Inputs.range([0, 0.99], {label: "EMA alpha", step: 0.01, value: 0.8})
viewof filterQ = Inputs.range([0.0001, 0.1], {label: "Kalman Q", step: 0.0001, value: 0.005})























{
  const ma = VM.filters.movingAverageFilter(noisy, filterK)
  const ema = VM.filters.emaFilter(noisy, filterAlpha)
  const kal = VM.filters.kalman1DFilter(noisy, {R: 0.09, Q: filterQ}).xs
  const c = chartColors   // reactive on the theme, so the lines repaint on a toggle
  const rows = []
  for (let i = 0; i &lt; noisy.length; i++) {
    rows.push({i, series: "measured", y: noisy[i]})
    rows.push({i, series: "moving average", y: ma[i]})
    rows.push({i, series: "EMA", y: ema[i]})
    rows.push({i, series: "Kalman", y: kal[i]})
  }
  return Plot.plot(VM.plotting.plotOptions({
    height: 320,
    x: {label: "sample"}, y: {label: null},
    color: {legend: true, domain: ["measured", "moving average", "EMA", "Kalman"], range: [c.muted, c.alt, c.ok, c.fn]},
    marks: [
      Plot.dot(rows.filter(d =&gt; d.series === "measured"), {x: "i", y: "y", stroke: "series", r: 2}),
      Plot.line(rows.filter(d =&gt; d.series !== "measured"), {x: "i", y: "y", stroke: "series", strokeWidth: 2})
    ]
  }))
}

Charts

ojs-chart-block
The wrapper around a chart and its companions. A floating legendOverlay is positioned against it, and it is what the fullscreen button enlarges – so a controls bar and legend inside it come along, and the chart keeps its aspect ratio.
Every chart wants one, even a chart that has neither a legend nor controls today. It also lets a chart in a layout-ncol column shrink with the column instead of forcing it wide.


ojs-chart-controls
A direct child of the chart block, holding the sliders that drive the chart – an iteration count, a step size. It renders as a bar directly above the chart, stays with the chart in fullscreen, and lays its controls out for that width: fluid slider tracks, compact number fields, labels beside controls.
Sliders in it get the play button. Combine with ojs-grid (class="ojs-chart-controls ojs-grid") for several sliders side by side.



viewof ctrlN = Inputs.range([1, 12], {label: "iterations n", step: 1, value: 4})








{
  const g = x =&gt; Math.cos(x)
  let x = 1
  const xs = [x], ys = [0]
  for (let i = 0; i &lt; ctrlN; i++) { const gx = g(x); xs.push(x, gx); ys.push(gx, gx); x = gx }
  const curveX = [], curveY = []
  for (let i = 0; i &lt;= 100; i++) { const t = i / 100 * 1.6; curveX.push(t); curveY.push(g(t)) }
  const div = document.createElement("div")
  div.style.height = "300px"
  Plotly.newPlot(div, [
    {x: curveX, y: curveY, name: "cos x", line: {color: chartColors.fn}},
    {x: [0, 1.6], y: [0, 1.6], name: "y = x", line: {color: chartColors.muted, dash: "dot"}},
    {x: xs, y: ys, name: "cobweb", line: {color: chartColors.alt, width: 1.5}, mode: "lines+markers", marker: {size: 5}}
  ], {showlegend: false, xaxis: {range: [0, 1.6]}, yaxis: {range: [0, 1.1]}, margin: {t: 8}})
  VM.plotting.autoResize(div)
  return div
}







