ojs-svg-block
For a chart drawn as inline SVG – Observable Plot, or a hand-built &lt;svg&gt; – which has no Plotly modebar. Put it on the same element as ojs-chart-block and nothing else: the library adds a fullscreen button pinned to the top-right corner of the figure, centers the figure in the block, and keeps its aspect ratio in fullscreen. The button survives re-runs of the cell.
The VM.discreteMath page and the starter’s observable-plot.qmd use it. Hover the chart there to see the button.


plotly-box-large
Full width, about three-quarters of the viewport tall with a floor of 500 px (less on a phone). It is the only size class shipped – there is no -small or -medium. For another height set div.style.height yourself, as the examples on this site do.

The page

VM = window.VM








viewof fText = Inputs.text({label: "f(x)", value: "sin(x) + x/3"})







viewof k = Inputs.range([1, 5], {label: "Frequency", step: 0.1, value: 1})









vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)
















mainPlot = {
  const f = VM.expressions.makeFunction(math, fText)
  const xs = [], ys = []
  for (let i = 0; i &lt;= 400; i++) {
    const x = -6 + 12 * i / 400
    xs.push(x)
    ys.push(f ? f(k * x) : NaN)
  }
  const div = document.createElement("div")
  div.className = "plotly-box-large"
  Plotly.newPlot(div, [
    {x: xs, y: ys, mode: "lines", name: fText, line: {color: chartColors.fn, width: 2.5}, showlegend: false}
  ], VM.plotting.layout({
    xaxis: {title: "x"},
    yaxis: {title: "f(kx)"},
    annotations: f ? [] : VM.plotting.emptyState("Couldn't parse that expression")
  }), VM.plotting.config())
  VM.plotting.autoResize(div)
  return div
}







