Live


viewof N = Inputs.range([1, 12], {label: "order N", step: 1, value: 5})







viewof recolor = Inputs.button("Recolor")









{
  recolor; chartColors   // re-run on the button and on a theme toggle
  const toXY = ([i, j, k]) =&gt; ({x: (j + k / 2) / N, y: (Math.sqrt(3) / 2) * k / N})
  const coloring = new Map()
  for (const t of VM.discreteMath.barycentricTriples(N)) coloring.set(t.join(","), VM.discreteMath.spernerColor(...t))
  const colorOf = t =&gt; coloring.get(t.join(","))
  const triangles = []
  for (const tri of VM.discreteMath.subTriangleTriples(N)) {
    const fill = VM.discreteMath.triangleFillColor(tri.map(colorOf))
    triangles.push({points: tri.map(toXY), fill})
  }
  const edges = []
  for (const {a, b} of VM.discreteMath.triangulationEdges(N)) {
    edges.push({...toXY(a), x2: toXY(b).x, y2: toXY(b).y, stroke: VM.discreteMath.pairColor(colorOf(a), colorOf(b)) ?? chartColors.muted})
  }
  const dots = []
  for (const t of VM.discreteMath.barycentricTriples(N)) dots.push({...toXY(t), color: colorOf(t)})
  const rainbow = triangles.filter(t =&gt; t.fill !== "none").length
  return Plot.plot(VM.plotting.plotOptions({
    width: 520, height: 470, axis: null, grid: false, x: {domain: [-0.05, 1.05]}, y: {domain: [-0.05, 0.92]},
    marks: [
      ...triangles.map(t =&gt; Plot.line(t.points.concat([t.points[0]]), {x: "x", y: "y", fill: t.fill, stroke: "none"})),
      Plot.link(edges, {x1: "x", y1: "y", x2: "x2", y2: "y2", stroke: "stroke", strokeWidth: 2}),
      Plot.dot(dots, {x: "x", y: "y", fill: d =&gt; VM.discreteMath.vertexColor(d.color), r: N &gt; 8 ? 4 : 6, stroke: chartColors.halo}),
      Plot.text([{x: 0.5, y: -0.03, t: `${rainbow} rainbow triangle${rainbow === 1 ? "" : "s"} (Sperner: always odd)`}], {x: "x", y: "y", text: "t", fill: chartColors.ink})
    ]
  }))
}

Overriding tokens
A plain declaration in your own stylesheet wins, whatever order the stylesheets load in (the library’s defaults are written to have zero specificity). In Quarto, list the file under format: html: css:.
/* your styles.css */
:root {
  --vm-accent: #b45309;
  --vm-color-fn: #b45309;
  --vm-font-sans: "Inter", system-ui, sans-serif;
}
body.quarto-dark {
  --vm-accent: #fbbf24;
  --vm-color-fn: #fbbf24;
}
Declare dark values under one of the dark selectors below. Tokens that don’t change between themes (--vm-radius, --vm-font-sans) need declaring only once.

Following the theme in a chart
Chart chrome – background, axes, gridlines, tooltip – re-themes itself on every chart when the theme flips. Nothing to do.
Chart traces don’t, because their colors are values your page baked in. The fix is the two cells at the top of every page:
vmTheme = Generators.observe(notify =&gt; VM.plotting.onThemeChange(notify))
chartColors = VM.plotting.colors(vmTheme)
Any cell that reads chartColors re-runs on a toggle. If a cell stores a color in a data structure rather than reading it at draw time, it must depend on chartColors too – a bare chartColors; line at the top of the cell is enough.
For translucent fills use VM.plotting.alpha("ok", 0.2) rather than an rgba(...) literal: the literal stays light-mode green after a toggle while the stroke next to it lightens.

{
  const div = document.createElement("div")
  div.style.height = "240px"
  const xs = [], ys = []
  for (let i = 0; i &lt;= 100; i++) { const x = i / 10; xs.push(x); ys.push(Math.exp(-x / 3) * Math.sin(2 * x)) }
  Plotly.newPlot(div, [
    {x: xs, y: ys, fill: "tozeroy", fillcolor: VM.plotting.alpha("ok", 0.2), line: {color: chartColors.ok, width: 2}, name: "alpha('ok', 0.2) under an ok stroke"},
    {x: [2.4, 5.5], y: [ys[24], ys[55]], mode: "markers", marker: {color: chartColors.alt, size: 12, line: {color: chartColors.halo, width: 2.5}}, name: "halo ring"}
  ], {legend: {x: 0.55, y: 0.98}, margin: {t: 8}})
  VM.plotting.autoResize(div)
  return div
}
